"""Linked List Cycle — Floyd's tortoise and hare.

If a cycle exists the fast pointer laps the slow one; otherwise it hits the end.

Time: O(n)   Space: O(1)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def hasCycle(self, head) -> bool:
        slow = fast = head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
            if slow is fast:
                return True
        return False
